// Normalizar payload Dionaea (Decisión 4 + grupo 13: riesgo por malware capturado)
const raw = $input.all()[0].json || {};
const event = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const conn = event.connection || {};
const download = event.download || {};

// Validar src_ip como inet (event.src_ip raíz — el log_json de dionaea emite src_ip a nivel raíz); fallback '0.0.0.0'
const ip = event.src_ip || conn.remote_host || event.remote_host || '';
const valid = /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) && ip.split('.').every(n => +n >= 0 && +n <= 255);

// dst_port ← event.dst_port (dionaea lo emite a nivel raíz); fallback connection.local_port
const rawPort = event.dst_port !== undefined && event.dst_port !== null ? event.dst_port : (conn.local_port || event.local_port);
const dstPort = rawPort === undefined || rawPort === null ? null : parseInt(rawPort, 10);

// Grupo 13: hash de malware presente → intento de compromiso con evidencia (HIGH 0.70);
// conexión sin captura → sondeo benigno (LOW 0.10).
const malwareHash = download.sha256 || download.sha256sum || download.md5 || null;
const riskScore = malwareHash ? 0.7 : 0.1;

const normalized = {
  timestamp: event.timestamp || new Date().toISOString(),
  source_honeypot: 'dionaea',
  src_ip: valid ? ip : '0.0.0.0',
  dst_port: Number.isNaN(dstPort) ? null : dstPort,
  protocol: conn.protocol || event.protocol || 'smb',
  username: null,
  commands: null,
  malware_hash: malwareHash,
  malware_filename: download.name || download.filename || null,
  playbook_id: 'PB-DIONAEA-v1.0',
  risk_score: riskScore,
  att_ck_technique: 'T1190',
  enrichment_data: null,
  raw_data: event
};

return [{ json: normalized }];
